mapper.select:
SELECT bill.id, bill.channel_id, bill.settle_month, bill.settle_amount, bill.bill_type, bill.bill_detail_url, bill.bill_detail_file_name, bill.settle_status, bill.enterprise_id, bill.remark, bill.deleted, bill.create_by, bill.create_time, bill.update_by, bill.update_time FROM employee_channel_bill bill WHERE bill.enterprise_id = #{enterpriseId} AND bill.deleted = 1
AND bill.settle_month IN
#{month}
AND bill.channel_id = #{channelId}
ORDER BY bill.create_time DESC, bill.id DESC

SELECT COALESCE(SUM(settle_amount), 0)
FROM employee_channel_bill
WHERE enterprise_id = #{enterpriseId}
  AND deleted = 1
  AND settle_status = '3'

    AND settle_month IN

        #{month}



    AND channel_id = #{channelId}

SELECT id, channel_id, settle_month, settle_amount, bill_type,
       bill_detail_url, bill_detail_file_name, settle_status,
       enterprise_id, remark, deleted, create_by, create_time,
       update_by, update_time
FROM employee_channel_bill
WHERE enterprise_id = #{enterpriseId}
  AND settle_month = #{settleMonth}
  AND channel_id = #{channelId}
  AND bill_type = #{billType}
  AND deleted = 1
ORDER BY create_time DESC, id DESC
FOR UPDATE

mapper.delete:
DELETE FROM employee_channel_bill
WHERE id = #{id}
  AND enterprise_id = #{enterpriseId}
  AND settle_status = '1'
  AND deleted = 1
